import{_ as p,a0 as s,w as n,s as l,ao as C,I as i,x as a,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Coverity 掃描報告首次發現開源軟件質量超過專有軟件 | LCTT x X-CMD","titleTemplate":false,"description":"Coverity 掃描報告首次發現開源軟件質量超過專有軟件 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Coverity 掃描報告首次發現開源軟件質量超過專有軟件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Coverity 掃描報告首次發現開源軟件質量超過專有軟件 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Coverity scan report finds open source software quality outpaces proprietary code for first time","title":"Coverity 掃描報告首次發現開源軟件質量超過專有軟件","tag":"201405","desc":""},"relativePath":"201405/Coverity scan report finds open source software quality outpaces proprietary code for first time.md","filePath":"[post].md"}'),d={name:"201405/Coverity scan report finds open source software quality outpaces proprietary code for first time.md"};function u(c,e,f,v,y,h){const t=s("Link");return n(),l("div",null,[e[11]||(e[11]=C('<h1 id="coverity-掃描報告首次發現開源軟件質量超過專有軟件" tabindex="-1">Coverity 掃描報告首次發現開源軟件質量超過專有軟件 <a class="header-anchor" href="#coverity-掃描報告首次發現開源軟件質量超過專有軟件" aria-label="Permalink to “Coverity 掃描報告首次發現開源軟件質量超過專有軟件”">​</a></h1><p><img src="http://www.ciol.com/IMG/550/80550/synopsys-logo-370x264.jpg" alt=""></p><p><strong>Coverity開啓了免費開發測試服務，允許任何對開源軟件質量感興趣的人查看項目</strong></p><p>特點 | CIOL Bureau</p><p>來自美國山景城（加州）的消息：Coverity公司（新思科技公司的一個子公司）發佈了2013年Coverity掃描開源軟件報告。</p><p>經過Coverity掃描服務以及按照Coverity開發測試平台的商業慣例，報告中詳細分析了關於7.5億行開源軟件代碼的分析，這是至今報告研究的最大的樣本量。</p><p>在2013年Coverity掃描報告中，他們分析了超過700個C/C++開源項目和一個匿名的企業項目的樣本。另外，報告中還強調了幾個流行的開源Java項目的分析結果，這些項目從2013年3月就加入了掃描服務。</p><p>Coverity掃描開源項目報告成為了一個被廣泛接受的衡量開放源代碼質量狀態的標準。在過去8年時間裏，Coverity掃描服務分析了超過1500個開源項目的數億行代碼——其中包括的C/C++項目中有NetBSD, FreeBSD，LibreOffice和Linux等，Java項目中有Apache Hadoop，HBase以及Cassandra等。</p><p>自2006年已來，掃描服務幫助開發者發現和修復了超過94,000缺陷。僅在2013年一年就修復了近50,000個缺陷——這是掃描服務的用户在一年中修復缺陷的最大數量。在這些缺陷中，其中有超過11,000的缺陷修復出現在掃描服務中的四個最大的項目：NetBSD，FreeBSD，LibreOffice和Linux。</p><h3 id="_2013年報告中重要發現包括" tabindex="-1">2013年報告中重要發現包括： <a class="header-anchor" href="#_2013年報告中重要發現包括" aria-label="Permalink to “2013年報告中重要發現包括：”">​</a></h3><h4 id="c-c-項目中開源軟件代碼質量超過專有軟件" tabindex="-1">C/C++項目中開源軟件代碼質量超過專有軟件 <a class="header-anchor" href="#c-c-項目中開源軟件代碼質量超過專有軟件" aria-label="Permalink to “C/C++項目中開源軟件代碼質量超過專有軟件”">​</a></h4><p>缺陷密度（每1,000行軟件代碼所含的缺陷）是一個通用的測量軟件質量的方法，缺陷密度1.0被認為是高質量軟件的公認的行業標準。</p><p>Coverity的分析中發現，掃描服務中的開源的C/C++項目的平均缺陷密度為 0.59，而為企業項目開發的專有C/C++代碼的缺陷密度為 0.72。在2013年，在所有不同大小的代碼庫中，掃描服務中的開源項目的代碼質量超過專有項目，這進一步強調了開源社區開發測試的堅定的承諾。</p><h4 id="linux繼續成為開源質量的基準" tabindex="-1">Linux繼續成為開源質量的基準 <a class="header-anchor" href="#linux繼續成為開源質量的基準" aria-label="Permalink to “Linux繼續成為開源質量的基準”">​</a></h4><p>通過利用掃描服務，Linux將修復一個新發現的缺陷的時間從122天減少到僅6天！從2008年第一個Coverity掃描報告發布後，掃描過的Linux版本的缺陷密度一直小於1.0。在2013年，Coverity掃描了超過850萬行Linux代碼並發現缺陷密度為 0.61。</p><h4 id="c-c-開發者修復了更多的高風險缺陷" tabindex="-1">C/C++開發者修復了更多的高風險缺陷 <a class="header-anchor" href="#c-c-開發者修復了更多的高風險缺陷" aria-label="Permalink to “C/C++開發者修復了更多的高風險缺陷”">​</a></h4><p>Coverity分析報告發現貢獻於開源Java項目的開發者修復的高風險缺陷的數量沒有貢獻於開源C/C++項目的開發者修復的多。</p><p>參加掃描服務的Java項目開發者只修復了13%的被指出的資源泄露，而C/C++項目開發者則修復了46%。這一方面可能是因為Java編程社區錯誤的安全感的原因，這種安全感是因為內建於語言的保護，比如垃圾收集。然而，垃圾收集是不可預測的，而且不能訪問系統資源，所以這些項目處於危險之中。</p><h4 id="hbase是java項目的基準" tabindex="-1">HBase是Java項目的基準 <a class="header-anchor" href="#hbase是java項目的基準" aria-label="Permalink to “HBase是Java項目的基準”">​</a></h4><p>Coverity分析了100個開源Java項目的超過800萬行代碼，包括流行的大數據項目Apache Hadoop 2.3 (320,000 行代碼)和Apache Cassandra (345,000 行代碼)。</p><p>自從在2013年8月加入掃描服務以來，Apache HBase (Hadoop的資料庫)修復了超過220個缺陷，其中包括比其他參加掃描服務Java項目更高比例的資源泄露（HBase的缺陷中資源泄露佔的比例為66%，而其他項目平均為13%）。</p><p>“如果説軟件正在吞食世界，那麼開源軟件則是帶頭衝鋒，”Coverity的產品高級總監Zack Samocha説，“我們的目標，包括Coverity掃描服務在內是幫助開源軟件社區創作高質量的軟件。基於這個報告的結果——以及這個日益流行的服務——使用開發測試的開源軟件項目繼續提升他們軟件的質量，這讓他們使整個行業更上一層樓。”</p><p>Coverity今天也宣佈已經開放了Coverity掃描服務，允許任何對開源軟件感興趣的人查看參與項目的進展。個人現在可以成為項目觀察者，這使他們可以跟蹤掃描服務中相關開源軟件的狀態，查看高級數據包括未解決和已修復的缺陷的數目以及缺陷密度。</p><p>“我們看到了請求掃描服務的人數的指數增長，他們僅僅是要監控被發現和被修復的缺陷。在許多情況下，這些人工作於大型的企業組織，那些企業組織在商業項目中使用開源軟件，”Samocha補充説。“通過對個人開放掃描服務，我們提升了查看開源項目代碼質量的新的可見度，他們的軟件供應鏈中正包含這些項目。”</p><hr>',25)),i("p",null,[e[1]||(e[1]=a("via: ",-1)),r(t,{href:"http://www.ciol.com/ciol/features/213112/coverity-scan-report-source-software-quality-outpaces-proprietary-code/page/1"},{default:o(()=>[...e[0]||(e[0]=[a("http://www.ciol.com/ciol/features/213112/coverity-scan-report-source-software-quality-outpaces-proprietary-code/page/1",-1)])]),_:1})]),i("p",null,[e[4]||(e[4]=a("譯者：",-1)),r(t,{href:"https://github.com/linuhap"},{default:o(()=>[...e[2]||(e[2]=[a("linuhap",-1)])]),_:1}),e[5]||(e[5]=a(" 校對：",-1)),r(t,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...e[3]||(e[3]=[a("Caroline",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=a("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[6]||(e[6]=[a("LCTT",-1)])]),_:1}),e[9]||(e[9]=a(" 原創翻譯，",-1)),r(t,{href:"http://linux.cn/"},{default:o(()=>[...e[7]||(e[7]=[a("Linux中國",-1)])]),_:1}),e[10]||(e[10]=a(" 榮譽推出",-1))])])}const _=p(d,[["render",u]]);export{T as __pageData,_ as default};
